#include <iostream>
using namespace std;

class Purr {
protected:
    int times;
public:
    Purr(int k) : times(k) { cout << "搭会打呼噜的那一半：" << times << endl; }
    void purr() const { cout << "呼噜 " << times << " {unit}" << endl; }
};

class Knead {
protected:
    int times;
public:
    Knead(int k) : times(k) { cout << "搭会踩奶的那一半：" << times << endl; }
    void knead() const { cout << "踩奶 " << times << " {unit}" << endl; }
};

class Baby : public Purr, public Knead {
public:
    Baby(int k) : Purr(k), Knead(k) { cout << "最后搭它自己那一半" << endl; }
};

int main() {
    int n = 0;
    cin >> n;

    Baby b(n);
    b.purr();
    b.knead();
    return 0;
}
